-- RF Performance — Avaliações e Certificações — Fase 1B
-- Catálogo público versionado; NÃO contém gabaritos, justificativas ou fontes.
-- Fonte: Sistema de Certificação Comercial - Consórcio de Veículos | versão 2026.08-v1
-- SHA-256 da fonte: e3ba2f891bf274be34439dc3e0007f0d9d3768b91c45f1a44aecae5197c852ab

begin;

do $$
declare
  v_org_count integer;
  v_plan_count integer;
  v_existing integer;
begin
  select count(*) into v_org_count
  from public.organizations
  where id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid
    and slug = 'rf-consorcios'
    and trade_name = 'RF Consórcios'
    and status = 'active'
    and archived_at is null;

  if v_org_count <> 1 then
    raise exception 'Fase 1B abortada: organização RF esperada não foi localizada ou não está ativa.';
  end if;

  select count(*) into v_plan_count
  from public.commercial_plans
  where id = 'baa2bbd9-7688-4fcc-92a8-16a96ca969db'::uuid
    and organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid
    and title = 'Plano de Aceleração Comercial — 90 Dias'
    and archived_at is null;

  if v_plan_count <> 1 then
    raise exception 'Fase 1B abortada: plano comercial de referência não foi localizado.';
  end if;

  select
    (select count(*) from public.certification_levels where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null) +
    (select count(*) from public.competency_domains where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null) +
    (select count(*) from public.assessment_tests where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null) +
    (select count(*) from public.assessment_questions where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null)
  into v_existing;

  if v_existing <> 0 then
    raise exception 'Fase 1B abortada: já existe catálogo de avaliações para a organização RF.';
  end if;
end $$;

