insert into public.assessment_version_questions (id, organization_id, test_version_id, question_id, sequence_no, points, is_required, metadata)
select id, organization_id, test_version_id, question_id, sequence_no, points, is_required, metadata
from payload;

-- Garantias pós-carga do catálogo público
do $$
declare
  v_bad integer;
begin
  select count(*) into v_bad
  from (
    select q.id
    from public.assessment_questions q
    left join public.assessment_question_options o
      on o.question_id = q.id and o.organization_id = q.organization_id and o.archived_at is null
    where q.organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and q.archived_at is null
    group by q.id
    having count(o.id) <> 4
  ) x;
  if v_bad <> 0 then
    raise exception 'Fase 1B abortada: existem questões sem exatamente quatro alternativas.';
  end if;

  if (select count(*) from public.assessment_questions where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null) <> 150 then
    raise exception 'Fase 1B abortada: contagem de questões diferente de 150.';
  end if;

  if (select count(*) from public.assessment_question_options where organization_id = '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid and archived_at is null) <> 600 then
    raise exception 'Fase 1B abortada: contagem de alternativas diferente de 600.';
  end if;
end $$;

